def sha(data):
    return hashlib.sha256(data).hexdigest()


def get_root():
    cwd = Path.cwd().resolve()
    if cwd.name != 'Interplex_MES_BE' or not (cwd / 'app/api/v1/api.py').is_file():
        raise RuntimeError('Run from the actual Interplex_MES_BE repository (not FE, not Downloads).')
    fe = cwd.parent / 'Interplex_MES_FE'
    if not fe.is_dir() or not (fe / 'docs/mes_agent/UPDATER_STANDARD.md').is_file():
        raise RuntimeError('FE sibling repository missing required updater standards.')
    return cwd.parent


def git_branch(repo):
    try:
        proc = subprocess.run(['git','-C',str(repo),'branch','--show-current'],
            text=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE, check=False, timeout=4)
        return proc.stdout.strip() if proc.returncode == 0 else 'UNKNOWN'
    except Exception:
        return 'UNKNOWN'


def embedded_files():
    data=zlib.decompress(base64.b85decode(PAYLOAD.encode('ascii')))
    out={}
    with zipfile.ZipFile(io.BytesIO(data)) as z:
        for item in z.infolist():
            p=Path(item.filename)
            if item.is_dir() or p.is_absolute() or '..' in p.parts or not p.parts or \
                    not item.filename.startswith('Interplex_MES_FE/') or \
                    not item.filename.endswith(('.jsx','.js','.md')):
                raise RuntimeError('Bad embedded path: '+item.filename)
            if item.filename in out:raise RuntimeError('Duplicate path: '+item.filename)
            raw=z.read(item)
            if sha(raw)!=AFTER.get(item.filename):
                raise RuntimeError('Corrupt embedded file: '+item.filename)
            out[item.filename]=raw
    if set(out)!=set(AFTER) or set(BASELINES)!=set(AFTER):
        raise RuntimeError('Embedded manifest mismatch')
    return out


def validate_environment(root,issues):
    print('SOURCE:',SOURCE_PROVENANCE)
    print('NOTE: no DB access in scan. V0002 VERIFY PASS is operator-confirmed, not checked live.')
    for repo in ('Interplex_MES_FE','Interplex_MES_BE'):
        actual=git_branch(root/repo)
        print(f"[{'PASS' if actual == 'phase2' else 'REJECT'}] Git {repo} branch observed={actual!r} expected='phase2'")
        if actual!='phase2':issues.append(f'Repository branch mismatch: {repo}: {actual}')
    if not ((3,11)<=sys.version_info[:2]<(3,15)):
        issues.append('Python 3.11..3.14 required')
    node=shutil.which('node')
    print(f"[{'PASS' if node else 'REJECT'}] Node available={bool(node)}")
    if not node:issues.append('Node.js required to build FE')
    pkg_path=root/'Interplex_MES_FE/package.json'
    try:
        pkg=json.loads(pkg_path.read_text(encoding='utf-8'))
        deps={**pkg.get('dependencies',{}),**pkg.get('devDependencies',{})}
        for d in ('react','axios','lucide-react','zustand','react-i18next'):
            ok=d in deps
            print(f"[{'PASS' if ok else 'REJECT'}] FE dependency {d}: {deps.get(d,'MISSING')}")
            if not ok:issues.append('Required FE dependency not declared: '+d)
    except Exception as error:
        issues.append('FE package.json absent or invalid: '+str(error))
    # Legacy dependencies not included in the current source collector but imported by patched FE.
    for path in ('Interplex_MES_FE/src/api/client.js',
                 'Interplex_MES_FE/src/components/common/BarcodeScanner.jsx',
                 'Interplex_MES_FE/src/utils/allocatorRoutingV4.js',
                 'Interplex_MES_FE/src/components/dashboard/WorkOrderCard.jsx'):
        ok=(root/path).is_file()
        print(f"[{'PASS' if ok else 'REJECT'}] referenced dependency exists: {path}")
        if not ok:issues.append('Referenced FE dependency missing: '+path)
    for collection,label in ((READONLY_PINS,'dependency/document'),(SQL_PINS,'V0002 release SQL')):
        for path,expected in sorted(collection.items()):
            target=root/path
            got=sha(target.read_bytes()) if target.is_file() else 'MISSING'
            state='PASS' if got==expected else 'REJECT'
            print(f'[{state}] {label} {path}: current={got} expected={expected}')
            if got!=expected:issues.append('Read-only pin mismatch: '+path)


def scan(root):
    print('=== MES2 RW PHASE C V1 | FRONTEND + DOCS ONLY ===')
    issues=[]
    validate_environment(root,issues)
    entries=embedded_files()
    states=[]
    for path,content in sorted(entries.items()):
        t=root/path
        before=BASELINES[path]
        got=sha(t.read_bytes()) if t.is_file() else None
        if t.exists() and not t.is_file():state='REJECT_NONFILE'
        elif got==AFTER[path]:state='AFTER'
        elif got==before:state='BEFORE'
        else:state='REJECT_DRIFT'
        print(f'[{state}] {path} | current={got or "MISSING"} | before={before or "ABSENT"} | after={AFTER[path]}')
        states.append(state)
        if state.startswith('REJECT'):issues.append('Unrecognized file state: '+path)
    if 'AFTER' in states and 'BEFORE' in states:
        issues.append('Partial installation. Do not apply a mixed BEFORE/AFTER tree.')
    if issues:
        for error in issues:print('[REJECT]',error)
        print('VERDICT: REJECT; no file changed')
        return None
    installed=all(state=='AFTER' for state in states)
    print('VERDICT: PASS — already installed (NO-OP)' if installed else 'VERDICT: PASS — ready for FE+docs APPLY')
    return {'installed':installed,'entries':entries}


def write_atomic(path,data,mode=None):
    path.parent.mkdir(parents=True, exist_ok=True)
    if path.exists() and not path.is_file():raise RuntimeError('Target not a regular file: '+str(path))
    fd,name=tempfile.mkstemp(prefix='.'+path.name+'.rw_phase_c_',dir=str(path.parent))
    try:
        with os.fdopen(fd,'wb') as f:
            f.write(data);f.flush();os.fsync(f.fileno())
        if mode is not None:os.chmod(name,mode)
        os.replace(name,path)
    finally:
        if os.path.exists(name):os.unlink(name)


def apply(root,plan):
    if plan['installed']:
        print('NO-OP: Phase C already installed; no writes, no new backup.');return
    if BACKUP_ROOT.exists():
        raise RuntimeError('Backup path already exists; do not overwrite: '+str(BACKUP_ROOT))
    entries=plan['entries']
    # Snapshot all exact bytes before mutating any file, outside both Git repos.
    records=[]
    BACKUP_ROOT.mkdir(parents=True,exist_ok=False)
    try:
        for path,content in sorted(entries.items()):
            target=root/path
            old=target.read_bytes() if target.is_file() else None
            mode=stat.S_IMODE(target.stat().st_mode) if target.is_file() else None
            record={'path':path, 'before':sha(old) if old is not None else None,
                    'after':sha(content), 'existed':old is not None,'mode':mode}
            if old is not None:
                backup=BACKUP_ROOT/'previous'/path
                backup.parent.mkdir(parents=True,exist_ok=True)
                backup.write_bytes(old)
            records.append(record)
        (BACKUP_ROOT/'manifest.json').write_text(json.dumps({
            'update_id':UPDATE_ID,'source':SOURCE_PROVENANCE,'changes':records},
            indent=2,ensure_ascii=False),encoding='utf-8')
        written=[]
        try:
            for record in records:
                path=record['path']
                write_atomic(root/path,entries[path],record['mode'])
                written.append(record)
                print('[APPLIED]',path)
        except BaseException:
            for record in reversed(written):
                target=root/record['path']
                if record['existed']:
                    write_atomic(target,(BACKUP_ROOT/'previous'/record['path']).read_bytes(),record['mode'])
                else:
                    target.unlink(missing_ok=True)
            print('[RECOVERED] Files written so far restored. Backup retained for inspection.')
            raise
    except BaseException:
        print('[INFO] Backup path:',BACKUP_ROOT)
        raise
    print('APPLIED: FE runtime+Markdown only. No DB, SQL, env or Backend modification.')
    print('BACKUP:',BACKUP_ROOT)
    print('NEXT: rebuild FE, browser hard-refresh, perform Dev API/SQL integration tests.')


def rollback(root):
    mf=BACKUP_ROOT/'manifest.json'
    if not mf.is_file():raise RuntimeError('Rollback manifest missing: '+str(mf))
    data=json.loads(mf.read_text(encoding='utf-8'))
    if data.get('update_id')!=UPDATE_ID:raise RuntimeError('Backup belongs to another updater')
    entries=embedded_files()
    if set(rec['path'] for rec in data['changes'])!=set(entries):
        raise RuntimeError('Backup manifest paths incomplete or unexpected.')
    for rec in data['changes']:
        t=root/rec['path']
        got=sha(t.read_bytes()) if t.is_file() else None
        if got!=rec['after']:
            raise RuntimeError('ROLLBACK REJECT: patched file modified: '+rec['path'])
        if rec['existed']:
            old=(BACKUP_ROOT/'previous'/rec['path']).read_bytes()
            if sha(old)!=rec['before']:raise RuntimeError('Corrupted rollback backup: '+rec['path'])
    print('WARNING: Rollback restores FE files ONLY. Persisted RW/FROZEN records are never reverted.')
    for rec in reversed(data['changes']):
        target=root/rec['path']
        if rec['existed']:
            write_atomic(target,(BACKUP_ROOT/'previous'/rec['path']).read_bytes(),rec['mode'])
        else:target.unlink(missing_ok=True)
        print('[RESTORED]',rec['path'])
    print('ROLLBACK COMPLETE — database, BE and SQL V0002 unchanged.')


def main():
    parser=argparse.ArgumentParser(description=__doc__)
    g=parser.add_mutually_exclusive_group(required=True)
    g.add_argument('--scan',action='store_true')
    g.add_argument('--apply',action='store_true')
    g.add_argument('--rollback',action='store_true')
    args=parser.parse_args()
    try:
        root=get_root()
        if args.rollback:rollback(root);return 0
        plan=scan(root)
        if plan is None:return 2
        if args.apply:apply(root,plan)
        return 0
    except Exception as exc:
        print('ERROR:',exc)
        return 2


if __name__=='__main__':
    sys.exit(main())
